// Aucun reseau, aucun stockage : la CSP du bac a sable les bloque de toute
// facon. Le pont window.ocModule est injecte avant ce script.
var u0Input = document.getElementById('u0');
var nInput = document.getElementById('n');
var nOut = document.getElementById('n-out');
var list = document.getElementById('terms');
var hint = document.getElementById('hint');
var last = 0;

function next(u) {
  return (u + 3) / 2;
}

function render() {
  var count = Number(nInput.value);
  var u = Number(u0Input.value);
  nOut.textContent = String(count);
  list.innerHTML = '';
  if (!isFinite(u)) {
    hint.textContent = 'Saisis un nombre pour u0.';
    return;
  }
  for (var i = 0; i <= count; i++) {
    var item = document.createElement('li');
    item.textContent = 'u' + i + ' = ' + Math.round(u * 10000) / 10000;
    list.appendChild(item);
    last = u;
    u = next(u);
  }
  hint.textContent = 'La suite converge vers 3, son unique point fixe : '
    + "l'ecart a 3 est divise par 2 a chaque etape.";
}

u0Input.addEventListener('input', render);
nInput.addEventListener('input', render);

document.getElementById('emit').addEventListener('click', function () {
  if (window.ocModule) {
    window.ocModule.emit('dernier-terme', { n: Number(nInput.value), valeur: last });
  }
});

render();

