// @oc-libs: matter
// Matter.js calcule la physique ; le dessin est fait à la main sur le canvas
// pour garder les couleurs du thème et tracer la trajectoire.
const { Engine, Bodies, Body, Composite, Resolver } = Matter;

// Sous ce seuil de vitesse, Matter traite un choc comme un simple appui (sans
// rebond) : abaissé pour que les petits rebonds restent élastiques, même sous
// la faible gravité de la Lune.
Resolver._restingThresh = 0.05;

const canvas = document.getElementById('scene');
const ctx = canvas.getContext('2d');
const eInput = document.getElementById('e');
const eOut = document.getElementById('e-out');
const gInput = document.getElementById('g');
const rows = document.getElementById('rows');
const hint = document.getElementById('hint');

const W = canvas.width;
const H = canvas.height;
const PX_PER_M = 120; // échelle : 1 m = 120 px
const GROUND = H - 24; // haut du sol, en px
const DROP_M = 2; // hauteur de lâcher
const R = 10; // rayon de la balle, en px
const MAX_BOUNCES = 8;
const MIN_BOUNCE_M = 0.03; // en dessous, le contact devient un appui (limite du solveur)
const STEP_MS = 1000 / 240; // pas fin : rebonds plus fidèles au modèle
const START_X = 24;
const START_Y = GROUND - DROP_M * PX_PER_M - R;

const fr = (x, digits) => x.toFixed(digits).replace('.', ',');
const color = (name) => getComputedStyle(document.documentElement).getPropertyValue(name).trim();

// Netteté sur écran haute densité : résolution interne multipliée, dessin inchangé.
const ratio = window.devicePixelRatio || 1;
canvas.width = W * ratio;
canvas.height = H * ratio;
ctx.scale(ratio, ratio);

let engine = null;
let ball = null;
let trail = [];
let apexes = [];
let rising = false;
let running = false;
let last = 0;
let pending = 0;

function heightOf(body) {
  return (GROUND - (body.position.y + R)) / PX_PER_M;
}

function drop() {
  const e = Number(eInput.value);
  const g = Number(gInput.value);
  engine = Engine.create();
  // Gravité de Matter en px/ms² (× gravity.scale = 0,001) : g m/s² → g·PX_PER_M/10⁶.
  engine.gravity.y = (g * PX_PER_M) / 1000;
  const ground = Bodies.rectangle(W / 2, GROUND + 50, W * 2, 100, {
    isStatic: true,
    restitution: 0,
    friction: 0,
  });
  ball = Bodies.circle(START_X, START_Y, R, {
    restitution: e,
    friction: 0,
    frictionAir: 0,
    frictionStatic: 0,
    inertia: Infinity,
  });
  // Vitesse horizontale choisie pour que MAX_BOUNCES rebonds tiennent dans le
  // cadre (Matter compte les vitesses en px par pas de base de 1/60 s).
  const t0 = Math.sqrt((2 * DROP_M) / g);
  let flight = t0;
  for (let k = 1; k <= MAX_BOUNCES; k++) flight += 2 * t0 * Math.pow(e, k);
  Body.setVelocity(ball, { x: (W - 60) / flight / 60, y: 0 });
  Composite.add(engine.world, [ground, ball]);

  trail = [];
  apexes = [];
  rising = false;
  running = true;
  last = performance.now();
  pending = 0;
  rows.innerHTML = '';
  hint.textContent = '';
  requestAnimationFrame(frame);
}

function recordApex() {
  const h = heightOf(ball);
  if (h < MIN_BOUNCE_M) {
    finish();
    return;
  }
  const previous = apexes.length ? apexes[apexes.length - 1] : DROP_M;
  apexes.push(h);
  const row = document.createElement('tr');
  row.innerHTML = '<td>' + apexes.length + '</td><td>' + fr(h, 3) + '</td><td>' + fr(h / previous, 2) + '</td>';
  rows.appendChild(row);
}

function finish() {
  running = false;
  const e = Number(eInput.value);
  // Moyenne géométrique des rapports successifs = (h_n / h_0)^(1/n).
  const measured = Math.pow(apexes[apexes.length - 1] / DROP_M, 1 / apexes.length);
  hint.textContent = 'Rapport moyen mesuré : ' + fr(measured, 2) + ' (valeur théorique e² = ' + fr(e * e, 2)
    + ', l’écart vient du calcul pas à pas). Sur un autre astre, les hauteurs restent les mêmes : '
    + 'seule la durée des rebonds change.';
  window.ocModule.emit('rebonds', { e: e, g: Number(gInput.value), hauteurs: apexes.map((h) => Math.round(h * 1000) / 1000) });
}

function frame(now) {
  if (!running) return;
  pending += Math.min(now - last, 100);
  last = now;
  while (pending >= STEP_MS && running) {
    Engine.update(engine, STEP_MS);
    pending -= STEP_MS;
    trail.push({ x: ball.position.x, y: ball.position.y });
    if (ball.velocity.y < -0.05) rising = true;
    if (rising && ball.velocity.y >= 0) {
      rising = false;
      recordApex();
      if (running && apexes.length >= MAX_BOUNCES) finish();
    }
    if (ball.position.x > W - R) finish();
  }
  draw();
  if (running) requestAnimationFrame(frame);
}

function draw() {
  const muted = color('--muted');
  ctx.clearRect(0, 0, W, H);

  // Sol et repère de la hauteur de lâcher.
  ctx.fillStyle = muted;
  ctx.fillRect(0, GROUND, W, 2);
  ctx.setLineDash([4, 4]);
  ctx.strokeStyle = muted;
  ctx.beginPath();
  ctx.moveTo(0, GROUND - DROP_M * PX_PER_M);
  ctx.lineTo(W, GROUND - DROP_M * PX_PER_M);
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = muted;
  ctx.font = '12px system-ui, sans-serif';
  ctx.fillText('2 m', W - 30, GROUND - DROP_M * PX_PER_M - 6);

  // Trajectoire.
  ctx.strokeStyle = color('--accent');
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  trail.forEach((p, i) => (i ? ctx.lineTo(p.x, p.y) : ctx.moveTo(p.x, p.y)));
  ctx.stroke();

  // Balle (à sa position de lâcher tant qu'elle n'est pas partie).
  const position = ball ? ball.position : { x: START_X, y: START_Y };
  ctx.fillStyle = color('--warm');
  ctx.beginPath();
  ctx.arc(position.x, position.y, R, 0, 2 * Math.PI);
  ctx.fill();
}

eInput.addEventListener('input', () => {
  eOut.textContent = fr(Number(eInput.value), 2);
});
document.getElementById('drop').addEventListener('click', drop);
draw();

