// @oc-libs: chart
// Chart.js trace les courbes ; le modèle est intégré ici (Runge-Kutta 4).
const inputs = ['a', 'b', 'c'].map((id) => document.getElementById(id));
const view = document.getElementById('view');
const summary = document.getElementById('summary');

const YEARS = 60;
const DT = 0.02; // pas d'intégration, en années
const SAMPLE = 25; // un point tracé tous les 25 pas (0,5 an)
const X0 = 40; // lièvres au départ (milliers)
const Y0 = 9; // lynx au départ (milliers)
const CONVERSION = 0.5; // part des proies mangées convertie en naissances de lynx

const fr = (x, digits) => x.toFixed(digits).replace('.', ',');
const css = (name) => getComputedStyle(document.documentElement).getPropertyValue(name).trim();

// dx/dt = a·x − b·x·y (proies) ; dy/dt = d·x·y − c·y (prédateurs), d = CONVERSION·b.
function simulate(a, b, c) {
  const d = CONVERSION * b;
  const f = (x, y) => [a * x - b * x * y, d * x * y - c * y];
  let x = X0;
  let y = Y0;
  const points = [{ t: 0, x, y }];
  for (let i = 1; i <= YEARS / DT; i++) {
    const [k1x, k1y] = f(x, y);
    const [k2x, k2y] = f(x + (DT / 2) * k1x, y + (DT / 2) * k1y);
    const [k3x, k3y] = f(x + (DT / 2) * k2x, y + (DT / 2) * k2y);
    const [k4x, k4y] = f(x + DT * k3x, y + DT * k3y);
    x += (DT / 6) * (k1x + 2 * k2x + 2 * k3x + k4x);
    y += (DT / 6) * (k1y + 2 * k2y + 2 * k3y + k4y);
    if (i % SAMPLE === 0) points.push({ t: i * DT, x, y });
  }
  return points;
}

// Années des maxima locaux d'une série (pour la période et le décalage des pics).
function peaks(points, key) {
  const years = [];
  for (let i = 1; i < points.length - 1; i++) {
    if (points[i][key] > points[i - 1][key] && points[i][key] >= points[i + 1][key]) years.push(points[i].t);
  }
  return years;
}

Chart.defaults.font.family = 'system-ui, -apple-system, "Segoe UI", Roboto, sans-serif';
Chart.defaults.color = css('--muted');
Chart.defaults.borderColor = css('--line');

const chart = new Chart(document.getElementById('chart'), {
  type: 'line',
  data: { datasets: [] },
  options: {
    // Largeur disponible, hauteur déduite du ratio (plus haut sur écran
    // étroit) : jamais de la hauteur de l'iframe, elle-même ajustée au contenu.
    responsive: true,
    maintainAspectRatio: true,
    aspectRatio: document.documentElement.clientWidth < 520 ? 1.2 : 1.8,
    animation: false,
    interaction: { mode: 'nearest', intersect: false },
    elements: { point: { radius: 0 } },
    plugins: { legend: { position: 'bottom' } },
    scales: {
      x: { type: 'linear', title: { display: true } },
      y: { type: 'linear', beginAtZero: true, title: { display: true } },
    },
  },
});

function update() {
  const [a, b, c] = inputs.map((input) => Number(input.value));
  document.getElementById('a-out').textContent = fr(a, 2);
  document.getElementById('b-out').textContent = fr(b, 3);
  document.getElementById('c-out').textContent = fr(c, 2);

  const points = simulate(a, b, c);
  const hare = css('--accent');
  const lynx = css('--warm');
  const { x: xAxis, y: yAxis } = chart.options.scales;
  if (view.value === 'time') {
    chart.data.datasets = [
      { label: 'Lièvres (milliers)', data: points.map((p) => ({ x: p.t, y: p.x })), borderColor: hare, backgroundColor: hare },
      { label: 'Lynx (milliers)', data: points.map((p) => ({ x: p.t, y: p.y })), borderColor: lynx, backgroundColor: lynx },
    ];
    xAxis.title.text = 'Années';
    yAxis.title.text = 'Effectif (milliers)';
  } else {
    chart.data.datasets = [
      { label: 'Trajectoire (lièvres, lynx)', data: points.map((p) => ({ x: p.x, y: p.y })), borderColor: hare, backgroundColor: hare },
    ];
    xAxis.title.text = 'Lièvres (milliers)';
    yAxis.title.text = 'Lynx (milliers)';
  }
  chart.update();

  const harePeaks = peaks(points, 'x');
  const lynxPeaks = peaks(points, 'y');
  const period = harePeaks.length > 1 ? (harePeaks[harePeaks.length - 1] - harePeaks[0]) / (harePeaks.length - 1) : null;
  const lag = harePeaks.length && lynxPeaks.length ? (lynxPeaks.find((t) => t > harePeaks[0]) ?? lynxPeaks[0]) - harePeaks[0] : null;
  summary.textContent = period === null
    ? 'Pas de cycle complet sur ' + YEARS + ' ans avec ces réglages.'
    : 'Cycles d’environ ' + fr(period, 1) + ' ans ; chaque pic de lynx suit celui des lièvres de '
      + fr(lag, 1) + ' an(s) : les prédateurs prospèrent quand les proies abondent, puis les font chuter.';
  window.ocModule.emit('cycles', { a, b, c, periode: period === null ? null : Math.round(period * 10) / 10 });
}

inputs.forEach((input) => input.addEventListener('input', update));
view.addEventListener('change', update);
update();

