// @oc-libs: p5
// p5.js 2.x en « mode global » : setup() et draw() sont appelées par p5.
const W = 640;
const BOX_H = 230; // enceinte des molécules
const PLOT_H = 80; // courbe de la part passée à droite
const H = BOX_H + PLOT_H;
const MEMBRANE = W / 2;
const PORE_H = 28;
const COUNT = 160;
const R = 3;
const SPEEDS = [0, 1.5, 3, 5]; // vitesse des molécules (px par image), par niveau d'agitation
const AGITATION = ['', 'faible', 'moyenne', 'forte'];
const HISTORY = 360; // points de la courbe : un toutes les 10 images, soit 1 min à 60 images/s

const poresInput = document.getElementById('pores');
const agitationInput = document.getElementById('agitation');
const pauseButton = document.getElementById('pause');
const summary = document.getElementById('summary');

const css = (name) => getComputedStyle(document.documentElement).getPropertyValue(name).trim();

let molecules = [];
let history = [];
let started = 0;
let reported = false;

// Ordonnées [haut, bas] des pores, répartis sur la hauteur de la membrane.
function pores() {
  const n = Number(poresInput.value);
  return Array.from({ length: n }, (_, i) => {
    const center = ((i + 1) * BOX_H) / (n + 1);
    return [center - PORE_H / 2, center + PORE_H / 2];
  });
}

function restart() {
  // Toutes les molécules démarrent dans le compartiment de gauche.
  molecules = Array.from({ length: COUNT }, () => ({
    x: random(R + 2, MEMBRANE - R - 2),
    y: random(R + 2, BOX_H - R - 2),
    heading: random(TWO_PI),
  }));
  history = [];
  started = millis();
  reported = false;
}

function setup() {
  const canvas = createCanvas(W, H);
  canvas.parent('stage');
  describe('Deux compartiments séparés par une membrane percée de pores ; des molécules passent de gauche à droite. Une courbe montre la part des molécules à droite au cours du temps.');
  restart();
}

function draw() {
  const holes = pores();
  const speed = SPEEDS[Number(agitationInput.value)];
  for (const m of molecules) {
    // Trajectoire rectiligne légèrement déviée à chaque image (chocs),
    // rebond sur les parois de l'enceinte.
    m.heading += random(-0.4, 0.4);
    let x = m.x + speed * cos(m.heading);
    const y = m.y + speed * sin(m.heading);
    if (x < R || x > W - R) m.heading = PI - m.heading;
    if (y < R || y > BOX_H - R) m.heading = -m.heading;
    // La membrane ne se franchit qu'au droit d'un pore ; ailleurs, rebond.
    const crosses = (m.x < MEMBRANE) !== (x < MEMBRANE);
    if (crosses && !holes.some(([top, bottom]) => y > top + R && y < bottom - R)) {
      m.heading = PI - m.heading;
      x = m.x;
    }
    m.x = constrain(x, R, W - R);
    m.y = constrain(y, R, BOX_H - R);
  }

  const right = molecules.filter((m) => m.x > MEMBRANE).length;
  if (frameCount % 10 === 0) history.push(right / COUNT);
  if (history.length > HISTORY) history.shift();

  background(css('--sky'));
  noStroke();

  // Membrane et pores.
  fill(css('--muted'));
  let top = 0;
  for (const [start, end] of [...holes, [BOX_H, BOX_H]]) {
    rect(MEMBRANE - 2, top, 4, start - top);
    top = end;
  }

  // Molécules.
  fill(css('--warm'));
  for (const m of molecules) circle(m.x, m.y, 2 * R);

  // Courbe : part des molécules à droite, avec le repère de l'équilibre (50 %).
  fill(css('--paper'));
  rect(0, BOX_H, W, PLOT_H);
  stroke(css('--line'));
  drawingContext.setLineDash([4, 4]);
  line(0, BOX_H + PLOT_H / 2, W, BOX_H + PLOT_H / 2);
  drawingContext.setLineDash([]);
  noFill();
  stroke(css('--accent'));
  strokeWeight(2);
  beginShape();
  history.forEach((share, i) => vertex((i * W) / HISTORY, BOX_H + PLOT_H - 4 - share * (PLOT_H - 8)));
  endShape();
  strokeWeight(1);
  noStroke();
  fill(css('--muted'));
  textSize(14);
  text('part des molécules à droite (1 min) — équilibre à 50 %', 8, BOX_H + 16);

  if (frameCount % 15 === 0) {
    const seconds = Math.round((millis() - started) / 1000);
    summary.textContent = holes.length === 0
      ? 'Membrane imperméable : aucune molécule ne passe.'
      : 'À gauche : ' + (COUNT - right) + ' · à droite : ' + right + ' — '
        + Math.round((100 * right) / COUNT) + ' % ont traversé en ' + seconds + ' s.';
    if (!reported && right >= 0.45 * COUNT) {
      reported = true;
      window.ocModule.emit('equilibre', { secondes: seconds, pores: holes.length, agitation: AGITATION[Number(agitationInput.value)] });
    }
  }
}

poresInput.addEventListener('input', () => {
  document.getElementById('pores-out').textContent = poresInput.value;
});
agitationInput.addEventListener('input', () => {
  document.getElementById('agitation-out').textContent = AGITATION[Number(agitationInput.value)];
});
document.getElementById('restart').addEventListener('click', restart);
pauseButton.addEventListener('click', () => {
  const paused = isLooping();
  if (paused) noLoop();
  else loop();
  pauseButton.setAttribute('aria-pressed', String(paused));
  pauseButton.textContent = paused ? 'Reprendre' : 'Pause';
});

