// @oc-libs: jsxgraph
// JSXGraph trace la courbe, le point mobile (« glider ») et sa tangente ; la
// saisie de f(x) est compilée par JessieCode, le langage de JSXGraph.
const exprInput = document.getElementById('expr');
const derivativeBox = document.getElementById('show-derivative');
const aInput = document.getElementById('a');
const readout = document.getElementById('readout');
const error = document.getElementById('error');

const css = (name) => getComputedStyle(document.documentElement).getPropertyValue(name).trim();
const fr = (x) => (Math.round(x * 100) / 100).toString().replace('.', ',').replace('-', '−');

// Couleurs du thème (clair ou sombre) pour les axes et les textes.
const axisStyle = {
  strokeColor: css('--muted'),
  highlightStrokeColor: css('--muted'),
  ticks: { strokeColor: css('--line'), label: { strokeColor: css('--muted') } },
};
JXG.Options.text.strokeColor = css('--ink');

const board = JXG.JSXGraph.initBoard('box', {
  boundingbox: [-4, 3, 4, -3],
  axis: true,
  defaultAxes: { x: axisStyle, y: axisStyle },
  showCopyright: false,
  showNavigation: false,
  keyboard: { enabled: true },
});

let f = (x) => x ** 3 / 3 - x;
const df = (x) => JXG.Math.Numerics.D(f)(x);

const curve = board.create('functiongraph', [(x) => f(x)], { strokeColor: css('--accent'), strokeWidth: 2.5, highlight: false });
const derivative = board.create('functiongraph', [(x) => df(x)], {
  strokeColor: css('--muted'),
  dash: 2,
  highlight: false,
  visible: false,
});
const point = board.create('glider', [1.5, f(1.5), curve], {
  name: 'M',
  size: 5,
  fillColor: css('--warm'),
  strokeColor: css('--warm'),
  label: { offset: [8, 12], strokeColor: css('--ink') },
});
board.create('tangent', [point], { strokeColor: css('--warm'), strokeWidth: 1.5, dash: 1 });

function describe() {
  const a = point.X();
  const slope = df(a);
  const intercept = f(a) - slope * a;
  aInput.value = String(a);
  readout.textContent = 'a = ' + fr(a) + ' ; f(a) = ' + fr(f(a)) + ' ; f′(a) = ' + fr(slope)
    + ' — tangente : y = ' + fr(slope) + 'x ' + (intercept < 0 ? '− ' : '+ ') + fr(Math.abs(intercept));
}

function moveTo(a) {
  point.moveTo([a, f(a)]);
  board.update();
  describe();
}

function plot() {
  try {
    const compiled = board.jc.snippet(exprInput.value, true, 'x', true);
    const probe = compiled(0.5);
    if (typeof probe !== 'number') throw new Error();
    f = compiled;
    error.textContent = '';
  } catch {
    error.textContent = 'Expression non reconnue. Exemples : x^2, sin(x), exp(-x^2), 1/(1+x^2).';
    return;
  }
  curve.updateCurve();
  moveTo(point.X());
}

document.getElementById('form').addEventListener('submit', (event) => {
  event.preventDefault(); // pas de soumission : la CSP du module l'interdit
  plot();
});
derivativeBox.addEventListener('change', () => {
  derivative.setAttribute({ visible: derivativeBox.checked });
});
aInput.addEventListener('input', () => moveTo(Number(aInput.value)));
point.on('drag', describe);
point.on('up', () => {
  window.ocModule.emit('tangente', { a: point.X(), pente: df(point.X()) });
});
describe();

