// @oc-libs: d3
// D3 calcule la disposition du cladogramme (d3.hierarchy, d3.cluster : les
// groupes actuels alignés à droite) et anime les transitions ; les données
// sont écrites ici, jamais chargées par URL.
const data = {
  name: 'Vertébrés', trait: 'une colonne vertébrale',
  children: [
    { name: 'Chondrichthyens', trait: 'un squelette cartilagineux', example: 'requin, raie' },
    {
      name: 'Ostéichthyens', trait: 'un squelette osseux',
      children: [
        { name: 'Actinoptérygiens', trait: 'des nageoires rayonnées', example: 'truite, thon' },
        {
          name: 'Sarcoptérygiens', trait: 'des nageoires charnues',
          children: [
            { name: 'Actinistiens', trait: 'une nageoire caudale à trois lobes', example: 'cœlacanthe' },
            {
              name: 'Tétrapodes', trait: 'quatre membres à doigts',
              children: [
                { name: 'Lissamphibiens', trait: 'une peau nue et humide', example: 'grenouille, salamandre' },
                {
                  name: 'Amniotes', trait: 'un œuf à amnios',
                  children: [
                    { name: 'Mammifères', trait: 'des poils et des mamelles', example: 'souris, humain' },
                    {
                      name: 'Sauropsides', trait: 'une peau couverte d’écailles de kératine',
                      children: [
                        { name: 'Lépidosauriens', trait: 'une mue de la peau entière', example: 'lézard, serpent' },
                        { name: 'Tortues', trait: 'une carapace', example: 'tortue d’Hermann' },
                        {
                          name: 'Archosauriens', trait: 'une ouverture du crâne devant l’œil',
                          children: [
                            { name: 'Crocodiliens', trait: 'un palais secondaire osseux', example: 'crocodile' },
                            { name: 'Oiseaux', trait: 'des plumes et un bec sans dents', example: 'pigeon, manchot' },
                          ],
                        },
                      ],
                    },
                  ],
                },
              ],
            },
          ],
        },
      ],
    },
  ],
};

const DX = 34; // écart vertical entre feuilles
const DY = 80; // écart horizontal entre niveaux
const MARGIN = { left: 90, right: 140 };

const title = document.getElementById('panel-title');
const text = document.getElementById('panel-text');
const toggle = document.getElementById('toggle');

const root = d3.hierarchy(data);
root.descendants().forEach((d, i) => {
  d.id = i;
  d.hidden = null; // enfants repliés
});
const layout = d3.cluster().nodeSize([DX, DY]);
// Liens en équerre (tradition des cladogrammes) : vertical au nœud parent,
// puis horizontal jusqu'au groupe — le nom d'un embranchement se pose dessus.
const link = (d) => 'M' + d.source.y + ',' + d.source.x + 'V' + d.target.x + 'H' + d.target.y;

// Le SVG s'adapte à la LARGEUR par son viewBox ; sa hauteur suit le ratio.
const svg = d3.select('#tree').append('svg').attr('role', 'group').attr('aria-label', 'Arbre de parenté des vertébrés');
const links = svg.append('g').attr('class', 'links');
// Branche d'entrée de la racine, qui porte son nom comme les autres embranchements.
const stub = links.append('path');
const nodes = svg.append('g').attr('class', 'nodes');
let selected = root;

function select(d) {
  selected = d;
  title.textContent = d.data.name;
  text.textContent = 'Caractère acquis : ' + d.data.trait + '.'
    + (d.data.example ? ' Exemples : ' + d.data.example + '.' : ' Tous les groupes à sa droite en héritent.');
  const foldable = Boolean(d.children || d.hidden) && d !== root;
  toggle.hidden = !foldable;
  toggle.textContent = d.children ? 'Replier ce groupe' : 'Déplier ce groupe';
  window.ocModule.emit('groupe', { nom: d.data.name });
  update();
}

function fold(d) {
  [d.children, d.hidden] = [d.hidden, d.children];
  select(d);
}

function update() {
  layout(root);
  const all = root.descendants();
  const [x0, x1] = d3.extent(all, (d) => d.x);
  const width = MARGIN.left + root.height * DY + MARGIN.right;
  const viewBox = [-MARGIN.left, x0 - DX, width, x1 - x0 + 1.6 * DX];
  // Premier rendu posé d'emblée, les suivants animés.
  (svg.attr('viewBox') ? svg.transition().duration(300) : svg).attr('viewBox', viewBox);

  const t = svg.transition().duration(300);
  stub.attr('d', 'M' + -MARGIN.left * 0.8 + ',' + root.x + 'H0');
  links.selectAll('path.link')
    .data(root.links(), (d) => d.target.id)
    .join(
      (enter) => enter.append('path').attr('class', 'link').attr('d', link),
      (update) => update,
      (exit) => exit.remove(),
    )
    .transition(t)
    .attr('d', link);

  nodes.selectAll('g.node')
    .data(all, (d) => d.id)
    .join((enter) => {
      const g = enter.append('g')
        .attr('class', 'node')
        .attr('tabindex', 0)
        .attr('role', 'button')
        .attr('transform', (d) => 'translate(' + d.y + ',' + d.x + ')')
        .on('click', (event, d) => select(d))
        .on('keydown', (event, d) => {
          if (event.key === 'Enter' || event.key === ' ') {
            event.preventDefault();
            select(d);
          }
        });
      g.append('circle').attr('r', 6);
      return g;
    })
    .attr('aria-label', (d) => d.data.name + (d.hidden ? ' (replié)' : ''))
    // Nom à droite d'un groupe terminal, sur sa branche pour un embranchement.
    .each(function (d) {
      const leaf = !d.children;
      d3.select(this).selectAll('text').data([d]).join('text')
        .attr('x', leaf ? 10 : -6)
        .attr('dy', leaf ? '0.32em' : '-0.55em')
        .attr('text-anchor', leaf ? 'start' : 'end')
        .text(d.data.name);
    })
    .classed('selected', (d) => d === selected)
    .classed('folded', (d) => Boolean(d.hidden))
    .transition(t)
    .attr('transform', (d) => 'translate(' + d.y + ',' + d.x + ')');
}

toggle.addEventListener('click', () => fold(selected));
update();

