:root {
  color-scheme: light dark;
  --ink: #1b1b1f;
  --muted: #5b5b66;
  --line: #d5d5dd;
  --accent: #2f5bd0;
  --warm: #c2410c;
  --paper: #ffffff;
  --sky: #eef3ff;
}

@media (prefers-color-scheme: dark) {
  :root {
    --ink: #e9e9ef;
    --muted: #a2a2b0;
    --line: #3a3a45;
    --accent: #8aa9f5;
    --warm: #fb923c;
    --paper: #1b1b21;
    --sky: #232838;
  }
}

body {
  margin: 0;
  padding: 1rem;
  font: 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color: var(--ink);
  background: var(--paper);
}

h2 { margin: 0 0 0.25rem; font-size: 1.1rem; }
