// @oc-libs: three
// Three.js dessine la scène ; THREE.OrbitControls (inclus) la fait tourner.
const stage = document.getElementById('stage');
const select = document.getElementById('molecule');
const pairsBox = document.getElementById('pairs');
const spinBox = document.getElementById('spin');
const summary = document.getElementById('summary');

const css = (name) => getComputedStyle(document.documentElement).getPropertyValue(name).trim();
const deg = (d) => (d * Math.PI) / 180;
const SCALE = 1.5; // longueurs de liaison (Å) agrandies pour l'affichage

// Couleurs CPK usuelles et rayons d'affichage.
const ATOMS = {
  C: { color: 0x3b3b3b, radius: 0.42 },
  H: { color: 0xf2f2f2, radius: 0.28 },
  O: { color: 0xe0312b, radius: 0.4 },
  N: { color: 0x3050f8, radius: 0.4 },
};

// Direction d'une liaison faisant l'angle `polar` avec l'axe vertical, orientée `azimuth`.
const dir = (polar, azimuth) =>
  new THREE.Vector3(Math.sin(deg(polar)) * Math.cos(deg(azimuth)), Math.cos(deg(polar)), Math.sin(deg(polar)) * Math.sin(deg(azimuth)));

// Pyramide à base triangulaire : angle au sommet entre deux liaisons → angle à l'axe.
const pyramidPolar = (bond) => (Math.acos(-Math.sqrt((2 * Math.cos(deg(bond)) + 1) / 3)) * 180) / Math.PI;

const MOLECULES = {
  ch4: {
    turn: 30, // orientation initiale : aucun atome caché derrière le centre
    center: 'C', bond: 1.09, order: 1,
    ligands: [0, 120, 240].map((a) => dir(pyramidPolar(109.5), a)).concat([dir(0, 0)]),
    pairs: [],
    text: 'Méthane : quatre doublets liants autour du carbone, répartis en tétraèdre — angles de 109,5°.',
  },
  nh3: {
    turn: 30,
    center: 'N', bond: 1.01, order: 1,
    ligands: [0, 120, 240].map((a) => dir(pyramidPolar(107), a)),
    pairs: [dir(0, 0)],
    text: 'Ammoniac : trois liants et un doublet non liant, qui repousse plus fort et referme les angles à 107° — molécule pyramidale.',
  },
  h2o: {
    turn: 25,
    center: 'O', bond: 0.96, order: 1,
    ligands: [dir(180 - 104.5 / 2, 0), dir(180 - 104.5 / 2, 180)],
    pairs: [dir(55, 90), dir(55, 270)],
    text: 'Eau : deux liants et deux doublets non liants ; molécule coudée, angle de 104,5°.',
  },
  co2: {
    turn: 0,
    center: 'C', bond: 1.16, order: 2,
    ligands: [dir(90, 0), dir(90, 180)],
    ligandAtom: 'O',
    pairs: [],
    text: 'Dioxyde de carbone : deux doubles liaisons opposées, sans doublet non liant sur le carbone ; molécule linéaire, angle de 180°.',
  },
};

const scene = new THREE.Scene();
scene.background = new THREE.Color(css('--sky'));
const camera = new THREE.PerspectiveCamera(40, 1, 0.1, 100);
camera.position.set(0, 2.2, 5.6);
scene.add(new THREE.AmbientLight(0xffffff, 0.9));
const light = new THREE.DirectionalLight(0xffffff, 2.2);
light.position.set(4, 6, 5);
scene.add(light);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setPixelRatio(window.devicePixelRatio || 1);
stage.appendChild(renderer.domElement);
const controls = new THREE.OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.enablePan = false;
controls.minDistance = 3;
controls.maxDistance = 12;

// Taille : largeur du conteneur, hauteur au ratio (jamais la hauteur de la
// fenêtre — l'iframe s'ajuste au contenu).
function resize() {
  const width = stage.clientWidth;
  const height = Math.round(width * 0.62);
  renderer.setSize(width, height);
  camera.aspect = width / height;
  camera.updateProjectionMatrix();
}
new ResizeObserver(resize).observe(stage);

let molecule = new THREE.Group();
scene.add(molecule);

function sphere(position, radius, material) {
  const mesh = new THREE.Mesh(new THREE.SphereGeometry(radius, 40, 24), material);
  mesh.position.copy(position);
  return mesh;
}

function cylinder(from, to, radius, material) {
  const axis = new THREE.Vector3().subVectors(to, from);
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, axis.length(), 20), material);
  mesh.position.copy(from).addScaledVector(axis, 0.5);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), axis.normalize());
  return mesh;
}

function build() {
  const spec = MOLECULES[select.value];
  scene.remove(molecule);
  molecule = new THREE.Group();
  const material = (atom) => new THREE.MeshStandardMaterial({ color: ATOMS[atom].color, roughness: 0.45 });
  const bondMaterial = new THREE.MeshStandardMaterial({ color: 0x9a9aa6, roughness: 0.6 });
  const origin = new THREE.Vector3();
  molecule.add(sphere(origin, ATOMS[spec.center].radius, material(spec.center)));

  for (const direction of spec.ligands) {
    const atom = spec.ligandAtom ?? 'H';
    const end = direction.clone().multiplyScalar(spec.bond * SCALE);
    molecule.add(sphere(end, ATOMS[atom].radius, material(atom)));
    if (spec.order === 1) {
      molecule.add(cylinder(origin, end, 0.08, bondMaterial));
    } else {
      // Double liaison : deux cylindres parallèles, l'un au-dessus de l'autre.
      const offset = new THREE.Vector3(0, 0.11, 0);
      molecule.add(cylinder(origin.clone().add(offset), end.clone().add(offset), 0.06, bondMaterial));
      molecule.add(cylinder(origin.clone().sub(offset), end.clone().sub(offset), 0.06, bondMaterial));
    }
  }

  // Doublets non liants : lobes translucides.
  const lobe = new THREE.MeshStandardMaterial({ color: 0xf5b700, transparent: true, opacity: 0.45 });
  for (const direction of spec.pairs) {
    const mesh = new THREE.Mesh(new THREE.SphereGeometry(0.28, 32, 16), lobe);
    mesh.scale.set(1, 1.7, 1);
    mesh.position.copy(direction).multiplyScalar(0.75);
    mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), direction);
    mesh.userData.pair = true;
    mesh.visible = pairsBox.checked;
    molecule.add(mesh);
  }
  molecule.rotation.y = deg(spec.turn);
  scene.add(molecule);
  summary.textContent = spec.text;
  window.ocModule.emit('molecule', { nom: select.value });
}

function animate() {
  if (spinBox.checked) molecule.rotation.y += 0.008;
  controls.update();
  renderer.render(scene, camera);
  requestAnimationFrame(animate);
}

select.addEventListener('change', build);
pairsBox.addEventListener('change', () => {
  molecule.children.forEach((child) => {
    if (child.userData.pair) child.visible = pairsBox.checked;
  });
});
resize();
build();
animate();
